/** A variable font at each weight in [weights], with the same variation [axes] on all. */
private fun variableFontFamily(
  @FontRes font: Int,
  weights: List<Int>,
  vararg axes: FontVariation.Setting,
): FontFamily =
  FontFamily(
    weights.map { weight ->
      Font(
        font,
        FontWeight(weight),
        variationSettings =
          FontVariation.Settings(
            FontWeight(weight),
            FontStyle.Normal,
            FontVariation.weight(weight),
            *axes,
          ),
      )
    },
  )

