@Composable
fun VerifyTheme(darkTheme: Boolean = isSystemInDarkTheme(), content: @Composable () -> Unit) {
  MaterialExpressiveTheme(
    colorScheme =
      rememberDynamicColorScheme(
        seedColor = SeedColor,
        isDark = darkTheme,
        style = PaletteStyle.TonalSpot,
        contrastLevel = 0.0,
        specVersion = ColorSpec.SpecVersion.SPEC_2025,
      ),
    typography = AppTypography,
    shapes = AppShapes,
    motionScheme = MotionScheme.expressive(),
    content = content,
  )
}

@Serializable private data object HomeRoute : NavKey

@Serializable private data object DetailRoute : NavKey

@Serializable private data object ActionsRoute : NavKey

@Serializable private data object InputsRoute : NavKey

@Serializable private data object OverlaysRoute : NavKey

@Serializable private data object FabsRoute : NavKey

@Composable
fun VerifyApp() {
  VerifyTheme {
    val backStack = rememberNavBackStack(HomeRoute)
    val listDetailStrategy = rememberListDetailSceneStrategy<NavKey>()
    NavDisplay(
      backStack = backStack,
      onBack = { backStack.removeLastOrNull() },
      sceneStrategies = listOf(listDetailStrategy),
      entryProvider =
        entryProvider {
          entry<HomeRoute>(metadata = ListDetailSceneStrategy.listPane()) {
            HomeScreen(
              onNavigateToHome = { backStack.add(HomeRoute) },
              onNavigateToActions = { backStack.add(ActionsRoute) },
              onNavigateToInputs = { backStack.add(InputsRoute) },
              onNavigateToOverlays = { backStack.add(OverlaysRoute) },
              onNavigateToDetail = { backStack.add(DetailRoute) },
            )
          }
          entry<DetailRoute>(metadata = ListDetailSceneStrategy.detailPane()) {
            DetailScreen(onBack = { backStack.removeLastOrNull() })
          }
          entry<ActionsRoute> {
            ActionsScreen(
              onNavigateToHome = { backStack.add(HomeRoute) },
              onNavigateToActions = { backStack.add(ActionsRoute) },
              onNavigateToInputs = { backStack.add(InputsRoute) },
              onNavigateToOverlays = { backStack.add(OverlaysRoute) },
            )
          }
          entry<InputsRoute> {
            InputsScreen(
              onNavigateToHome = { backStack.add(HomeRoute) },
              onNavigateToActions = { backStack.add(ActionsRoute) },
              onNavigateToInputs = { backStack.add(InputsRoute) },
              onNavigateToOverlays = { backStack.add(OverlaysRoute) },
            )
          }
          entry<OverlaysRoute> {
            OverlaysScreen(
              onNavigateToHome = { backStack.add(HomeRoute) },
              onNavigateToActions = { backStack.add(ActionsRoute) },
              onNavigateToInputs = { backStack.add(InputsRoute) },
              onNavigateToOverlays = { backStack.add(OverlaysRoute) },
              onNavigateToFabs = { backStack.add(FabsRoute) },
            )
          }
          entry<FabsRoute> { FabsScreen(onBack = { backStack.removeLastOrNull() }) }
        },
    )
  }
}

@Composable
fun HomeScreen(
  modifier: Modifier = Modifier,
  rows: List<HomeRow> = HomeSample.rows,
  onNavigateToHome: () -> Unit = {},
  onNavigateToActions: () -> Unit = {},
  onNavigateToInputs: () -> Unit = {},
  onNavigateToOverlays: () -> Unit = {},
  onNavigateToDetail: () -> Unit = {},
) {
  val windowSizeClass = currentWindowAdaptiveInfoV2().windowSizeClass
  val atLeastMedium =
    windowSizeClass.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_MEDIUM_LOWER_BOUND)
  val atLeastExpanded =
    windowSizeClass.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_EXPANDED_LOWER_BOUND)
  val scrollBehavior = TopAppBarDefaults.exitUntilCollapsedScrollBehavior()
  Row(modifier = modifier) {
    if (atLeastMedium && !atLeastExpanded) {
      WideNavigationRail(state = rememberWideNavigationRailState()) {
        WideNavigationRailItem(
          railExpanded = false,
          selected = true,
          onClick = { onNavigateToHome() },
          icon = { Icon(painterResource(R.drawable.home), contentDescription = null) },
          label = { Text("Home") },
        )
        WideNavigationRailItem(
          railExpanded = false,
          selected = false,
          onClick = { onNavigateToActions() },
          icon = { Icon(painterResource(R.drawable.touch_app), contentDescription = null) },
          label = { Text("Actions") },
        )
        WideNavigationRailItem(
          railExpanded = false,
          selected = false,
          onClick = { onNavigateToInputs() },
          icon = { Icon(painterResource(R.drawable.tune), contentDescription = null) },
          label = { Text("Inputs") },
        )
        WideNavigationRailItem(
          railExpanded = false,
          selected = false,
          onClick = { onNavigateToOverlays() },
          icon = { Icon(painterResource(R.drawable.layers), contentDescription = null) },
          label = { Text("Overlays") },
        )
      }
    } else if (atLeastExpanded) {
      WideNavigationRail(
        state = rememberWideNavigationRailState(WideNavigationRailValue.Expanded),
      ) {
        WideNavigationRailItem(
          railExpanded = true,
          selected = true,
          onClick = { onNavigateToHome() },
          icon = { Icon(painterResource(R.drawable.home), contentDescription = null) },
          label = { Text("Home") },
        )
        WideNavigationRailItem(
          railExpanded = true,
          selected = false,
          onClick = { onNavigateToActions() },
          icon = { Icon(painterResource(R.drawable.touch_app), contentDescription = null) },
          label = { Text("Actions") },
        )
        WideNavigationRailItem(
          railExpanded = true,
          selected = false,
          onClick = { onNavigateToInputs() },
          icon = { Icon(painterResource(R.drawable.tune), contentDescription = null) },
          label = { Text("Inputs") },
        )
        WideNavigationRailItem(
          railExpanded = true,
          selected = false,
          onClick = { onNavigateToOverlays() },
