@Composable
fun DetailScreen(modifier: Modifier = Modifier, onBack: () -> Unit = {}) {
  val windowSizeClass = currentWindowAdaptiveInfoV2().windowSizeClass
  val atLeastMedium =
    windowSizeClass.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_MEDIUM_LOWER_BOUND)
  val atLeastExpanded =
    windowSizeClass.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_EXPANDED_LOWER_BOUND)
  Scaffold(
    modifier = modifier,
    topBar = {
      if (!atLeastExpanded) {
        TopAppBar(
          title = { Text("Detail") },
          navigationIcon = {
            IconButton(
              onClick = { onBack() },
              colors =
                IconButtonDefaults.iconButtonColors(
                  contentColor = MaterialTheme.colorScheme.onSurfaceVariant,
                ),
            ) {
              Icon(painterResource(R.drawable.arrow_back), contentDescription = "Back")
            }
          },
        )
      }
    },
  ) { innerPadding ->
    Column(
      modifier = Modifier.fillMaxSize().padding(innerPadding).padding(16.dp),
      verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
      Text("Detail pane", style = MaterialTheme.typography.headlineSmall)
      Text("Beside the home list at expanded widths.", style = MaterialTheme.typography.bodyLarge)
    }
  }
}

