@Composable
fun FabsScreen(modifier: Modifier = Modifier, onBack: () -> Unit = {}) {
  val scrollBehavior = TopAppBarDefaults.exitUntilCollapsedScrollBehavior()
  Scaffold(
    modifier = modifier.nestedScroll(scrollBehavior.nestedScrollConnection),
    topBar = {
      MediumFlexibleTopAppBar(
        title = { Text("Floating action buttons") },
        navigationIcon = {
          IconButton(
            onClick = { onBack() },
            colors =
              IconButtonDefaults.iconButtonColors(
                contentColor = MaterialTheme.colorScheme.onSurfaceVariant,
              ),
          ) {
            Icon(painterResource(R.drawable.arrow_back), contentDescription = "Back")
          }
        },
        scrollBehavior = scrollBehavior,
      )
    },
  ) { innerPadding ->
    Column(
      modifier =
        Modifier.fillMaxSize()
          .padding(innerPadding)
          .verticalScroll(rememberScrollState())
          .padding(16.dp),
      verticalArrangement = Arrangement.spacedBy(16.dp),
    ) {
      Row(
        horizontalArrangement = Arrangement.spacedBy(12.dp),
        verticalAlignment = Alignment.CenterVertically,
      ) {
        FloatingActionButton(
          onClick = {},
          modifier = Modifier.semantics { contentDescription = "Edit, small" },
        ) {
          Icon(painterResource(R.drawable.edit), contentDescription = "Edit, small")
        }
        MediumFloatingActionButton(
          onClick = {},
          modifier = Modifier.semantics { contentDescription = "Edit, medium" },
        ) {
          Icon(
            painterResource(R.drawable.edit),
            contentDescription = "Edit, medium",
            modifier = Modifier.size(FloatingActionButtonDefaults.MediumIconSize),
          )
        }
        LargeFloatingActionButton(
          onClick = {},
          modifier = Modifier.semantics { contentDescription = "Edit, large" },
        ) {
          Icon(
            painterResource(R.drawable.edit),
            contentDescription = "Edit, large",
            modifier = Modifier.size(FloatingActionButtonDefaults.LargeIconSize),
          )
        }
      }
      Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        ExtendedFloatingActionButton(
          onClick = {},
          icon = { Icon(painterResource(R.drawable.edit), contentDescription = null) },
          text = { Text("Compose") },
        )
        MediumExtendedFloatingActionButton(
          onClick = {},
          icon = {
            Icon(
              painterResource(R.drawable.edit),
              contentDescription = null,
              modifier = Modifier.size(FloatingActionButtonDefaults.MediumIconSize),
            )
          },
          text = { Text("Compose") },
        )
        LargeExtendedFloatingActionButton(
          onClick = {},
          icon = {
            Icon(
              painterResource(R.drawable.edit),
              contentDescription = null,
              modifier = Modifier.size(FloatingActionButtonDefaults.LargeIconSize),
            )
          },
          text = { Text("Compose") },
        )
      }
      FlexBox(
        config = {
          wrap(FlexWrap.Wrap)
          gap(12.dp)
        },
      ) {
        FloatingActionButton(
          onClick = {},
          modifier = Modifier.semantics { contentDescription = "primary-container" },
        ) {
          Icon(painterResource(R.drawable.palette), contentDescription = "primary-container")
        }
        FloatingActionButton(
          onClick = {},
          modifier = Modifier.semantics { contentDescription = "primary" },
          containerColor = MaterialTheme.colorScheme.primary,
          contentColor = MaterialTheme.colorScheme.onPrimary,
        ) {
          Icon(painterResource(R.drawable.palette), contentDescription = "primary")
        }
        FloatingActionButton(
          onClick = {},
          modifier = Modifier.semantics { contentDescription = "secondary-container" },
          containerColor = MaterialTheme.colorScheme.secondaryContainer,
          contentColor = MaterialTheme.colorScheme.onSecondaryContainer,
        ) {
          Icon(painterResource(R.drawable.palette), contentDescription = "secondary-container")
        }
        FloatingActionButton(
          onClick = {},
          modifier = Modifier.semantics { contentDescription = "secondary" },
          containerColor = MaterialTheme.colorScheme.secondary,
          contentColor = MaterialTheme.colorScheme.onSecondary,
        ) {
          Icon(painterResource(R.drawable.palette), contentDescription = "secondary")
        }
        FloatingActionButton(
          onClick = {},
          modifier = Modifier.semantics { contentDescription = "tertiary-container" },
          containerColor = MaterialTheme.colorScheme.tertiaryContainer,
          contentColor = MaterialTheme.colorScheme.onTertiaryContainer,
        ) {
